<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta
  name="viewport"
  content="width=device-width, initial-scale=1.0"
/>

<style>
html,
body {
  width: 100%;
  min-height: 100%;
  margin: 0;
}

.home-float {
  position: fixed;
  right: var(--home-right, 20px);
  bottom: var(--home-bottom, 24px);
  z-index: 9999;
  border: 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

.home-float img {
  display: block;
  width: var(--home-width, 76px);
  height: auto;
  user-select: none;
  -webkit-user-drag: none;
  animation:
    home-float-anim
    var(--home-duration, 2.4s)
    ease-in-out
    infinite;
}

.home-float.is-static img {
  animation: none;
}

.home-float:active img {
  transform: scale(
    var(--home-press-scale, 0.92)
  );
}

@keyframes home-float-anim {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(
      calc(
        var(--home-distance, 8px) * -1
      )
    );
  }
}
</style>
</head>

<body>
<button
  id="homeFloatButton"
  class="home-float"
  type="button"
  aria-label="回首页"
>
  <img
    id="homeFloatImage"
    src=""
    alt="回首页"
  />
</button>

<script>
window.HOME_BUTTON_CONFIG = {
  enabled: true,
  image:
    "https://s3.bmp.ovh/2026/08/03/YtXQ7fB6.png",
  alt: "回首页",
  width: 76,
  right: 20,
  bottom: 24,
  animationEnabled: true,
  animationDuration: 2.4,
  animationDistance: 8,
  pressScale: 0.92,
  targetSwipe: 0
};

(function () {
  "use strict";

  var config =
    window.HOME_BUTTON_CONFIG || {};

  var button =
    document.getElementById(
      "homeFloatButton"
    );

  var image =
    document.getElementById(
      "homeFloatImage"
    );

  if (!button || !image) {
    return;
  }

  function numberValue(
    value,
    fallback
  ) {
    var number = Number(value);

    return Number.isFinite(number)
      ? number
      : fallback;
  }

  if (config.enabled === false) {
    button.style.display = "none";
  }

  image.src = String(
    config.image || ""
  );

  image.alt = String(
    config.alt || "回首页"
  );

  button.setAttribute(
    "aria-label",
    image.alt
  );

  button.style.setProperty(
    "--home-width",
    numberValue(config.width, 76) + "px"
  );

  button.style.setProperty(
    "--home-right",
    numberValue(config.right, 20) + "px"
  );

  button.style.setProperty(
    "--home-bottom",
    numberValue(config.bottom, 24) + "px"
  );

  button.style.setProperty(
    "--home-duration",
    Math.max(
      0.1,
      numberValue(
        config.animationDuration,
        2.4
      )
    ) + "s"
  );

  button.style.setProperty(
    "--home-distance",
    numberValue(
      config.animationDistance,
      8
    ) + "px"
  );

  button.style.setProperty(
    "--home-press-scale",
    numberValue(
      config.pressScale,
      0.92
    )
  );

  if (
    config.animationEnabled === false
  ) {
    button.classList.add("is-static");
  }

  var returningHome = false;

  async function goHome() {
    if (returningHome) {
      return;
    }

    returningHome = true;

    try {
      if (
        typeof getChatMessages !==
          "function" ||
        typeof setChatMessages !==
          "function"
      ) {
        throw new Error(
          "当前页面无法使用酒馆助手的消息接口。"
        );
      }

      var targetSwipe = Number(
        config.targetSwipe
      );

      if (
        !Number.isInteger(targetSwipe) ||
        targetSwipe < 0
      ) {
        throw new Error(
          "首页开场白编号无效。"
        );
      }

      var messages =
        await getChatMessages("0", {
          include_swipes: true
        });

      var opening =
        Array.isArray(messages)
          ? messages[0]
          : null;

      if (
        !opening ||
        !Array.isArray(
          opening.swipes
        ) ||
        opening.swipes.length === 0
      ) {
        throw new Error(
          "没有找到存放主页的候选开场白。"
        );
      }

      if (
        targetSwipe >=
        opening.swipes.length
      ) {
        throw new Error(
          "首页编号超出当前开场白数量。"
        );
      }

      if (
        opening.swipe_id === targetSwipe
      ) {
        return;
      }

      await setChatMessages(
        [
          {
            message_id:
              opening.message_id,
            swipe_id: targetSwipe
          }
        ],
        {
          refresh: "affected"
        }
      );
    } catch (error) {
      console.error(
        "[通用回首页按钮]",
        error
      );

      window.alert(
        "这次没有成功回到首页。\n" +
          (
            error && error.message
              ? error.message
              : "请查看控制台中的错误信息。"
          )
      );
    } finally {
      returningHome = false;
    }
  }

  button.addEventListener(
    "click",
    goHome
  );
})();
</script>
</body>
</html>
